CREATE TABLE `carryover_project` (
  `item_id` bigint NOT NULL COMMENT '承接项目索引',
  `com_id` bigint NOT NULL COMMENT '所属企业',
  `store_id` bigint DEFAULT NULL COMMENT '所属门店',
  `team_id` bigint DEFAULT NULL COMMENT '所属团队',
  `owner_id` bigint DEFAULT NULL COMMENT '经营负责人',
  `batch_id` bigint NOT NULL COMMENT '所属承接任务',
  `status` varchar(16) NOT NULL COMMENT 'Draft/Ready/Confirmed/Applied/Locked/Cancelled',
  `version` int NOT NULL DEFAULT '1' COMMENT '草稿版本',
  `customer_name` varchar(64) DEFAULT NULL COMMENT '客户姓名',
  `customer_phone` varchar(32) DEFAULT NULL COMMENT '客户手机号',
  `community` varchar(128) DEFAULT NULL COMMENT '小区',
  `address` varchar(256) DEFAULT NULL COMMENT '房屋地址',
  `area` decimal(10,2) DEFAULT NULL COMMENT '面积',
  `manager_id` bigint DEFAULT NULL COMMENT '项目经理',
  `designer_id` bigint DEFAULT NULL COMMENT '设计师',
  `contract_no` varchar(64) DEFAULT NULL COMMENT '合同编号',
  `signed_amount` decimal(14,2) DEFAULT NULL COMMENT '原始签约金额',
  `current_amount` decimal(14,2) DEFAULT NULL COMMENT '当前合同金额',
  `signed_at` date DEFAULT NULL COMMENT '签约日期',
  `start_date` date DEFAULT NULL COMMENT '开工日期',
  `plan_end_date` date DEFAULT NULL COMMENT '计划完工日期',
  `project_name` varchar(128) DEFAULT NULL COMMENT '项目名称',
