  `current_issue` varchar(1000) DEFAULT NULL COMMENT '当前问题摘要',
  `receivable_outstanding` decimal(14,2) DEFAULT NULL COMMENT '期初未收金额',
  `receivable_due_date` date DEFAULT NULL COMMENT '期初应收到期日',
  `receivable_source_no` varchar(64) DEFAULT NULL COMMENT '期初应收原单号',
  `receivable_confirmed` bit(1) NOT NULL DEFAULT b'0' COMMENT '期初应收已确认',
  `payable_outstanding` decimal(14,2) DEFAULT NULL COMMENT '期初未付金额',
  `payable_due_date` date DEFAULT NULL COMMENT '期初应付到期日',
  `payable_payee_name` varchar(128) DEFAULT NULL COMMENT '期初应付收款方',
  `payable_source_no` varchar(64) DEFAULT NULL COMMENT '期初应付原单号',
  `payable_confirmed` bit(1) NOT NULL DEFAULT b'0' COMMENT '期初应付已确认',
  `cost_total` decimal(14,2) DEFAULT NULL COMMENT '接管前成本总额',
  `cost_status` varchar(16) NOT NULL DEFAULT 'Unknown' COMMENT 'Complete/TotalOnly/Unknown',
  `cost_missing_note` varchar(500) DEFAULT NULL COMMENT '接管前成本缺失说明',
  `legacy_id` varchar(128) DEFAULT NULL COMMENT '原系统项目 ID',
  `legacy_project_no` varchar(64) DEFAULT NULL COMMENT '原系统项目编号',
  `quote_id` bigint DEFAULT NULL COMMENT '接管基线报价',
  `contract_id` bigint DEFAULT NULL COMMENT '合同基线',
  `project_id` bigint DEFAULT NULL COMMENT '正式项目',
  `receivable_id` bigint DEFAULT NULL COMMENT '期初应收',
  `payable_id` bigint DEFAULT NULL COMMENT '期初应付',
  `applied_at` datetime(6) DEFAULT NULL COMMENT '承接完成时间',
  `cancelled_at` datetime(6) DEFAULT NULL COMMENT '取消时间',
  `cancel_reason` varchar(500) DEFAULT NULL COMMENT '取消原因',
  `locked_at` datetime(6) DEFAULT NULL COMMENT '锁定时间',
  `first_business_at` datetime(6) DEFAULT NULL COMMENT '首笔业务发生时间',
  `first_business_type` varchar(24) DEFAULT NULL COMMENT '首笔业务类型',
  `plan_status` varchar(16) NOT NULL DEFAULT 'NotStarted' COMMENT '接管后计划：NotStarted/Draft/Confirmed/Locked',
  `plan_version` int NOT NULL DEFAULT '0' COMMENT '接管后计划版本',
