  KEY `idx_carryover_project_company` (`com_id`,`item_id`),
  KEY `idx_carryover_project_batch` (`com_id`,`batch_id`,`item_id`),
  KEY `idx_carryover_project_status` (`com_id`,`status`,`item_id`),
  KEY `idx_carryover_project_store` (`com_id`,`store_id`,`item_id`),
  KEY `idx_carryover_project_team` (`com_id`,`team_id`,`item_id`),
  KEY `idx_carryover_project_owner` (`com_id`,`owner_id`,`item_id`),
  KEY `idx_carryover_project_quote` (`quote_id`),
  KEY `idx_carryover_project_contract` (`contract_id`),
  KEY `idx_carryover_project_result` (`project_id`),
  KEY `fk_carryover_project_store` (`store_id`),
  KEY `fk_carryover_project_team` (`team_id`),
  KEY `fk_carryover_project_owner` (`owner_id`),
  KEY `fk_carryover_project_batch` (`batch_id`),
  KEY `fk_carryover_project_manager` (`manager_id`),
  KEY `fk_carryover_project_designer` (`designer_id`),
  KEY `fk_carryover_project_receivable` (`receivable_id`),
  KEY `fk_carryover_project_payable` (`payable_id`),
  KEY `fk_carryover_project_locked_by` (`locked_by`),
  KEY `fk_carryover_project_plan_confirmed_by` (`plan_confirmed_by`),
  CONSTRAINT `fk_carryover_project_batch` FOREIGN KEY (`batch_id`) REFERENCES `carryover_batch` (`batch_id`),
  CONSTRAINT `fk_carryover_project_company` FOREIGN KEY (`com_id`) REFERENCES `db_tenant_company` (`com_id`),
  CONSTRAINT `fk_carryover_project_contract` FOREIGN KEY (`contract_id`) REFERENCES `db_project_contract` (`contract_id`),
  CONSTRAINT `fk_carryover_project_designer` FOREIGN KEY (`designer_id`) REFERENCES `db_tenant_employee` (`emp_id`),
  CONSTRAINT `fk_carryover_project_locked_by` FOREIGN KEY (`locked_by`) REFERENCES `db_tenant_employee` (`emp_id`),
  CONSTRAINT `fk_carryover_project_manager` FOREIGN KEY (`manager_id`) REFERENCES `db_tenant_employee` (`emp_id`),
  CONSTRAINT `fk_carryover_project_owner` FOREIGN KEY (`owner_id`) REFERENCES `db_tenant_employee` (`emp_id`),
  CONSTRAINT `fk_carryover_project_payable` FOREIGN KEY (`payable_id`) REFERENCES `db_finance_payable` (`payable_id`),
  CONSTRAINT `fk_carryover_project_plan_confirmed_by` FOREIGN KEY (`plan_confirmed_by`) REFERENCES `db_tenant_employee` (`emp_id`),
  CONSTRAINT `fk_carryover_project_quote` FOREIGN KEY (`quote_id`) REFERENCES `quote` (`quote_id`),
  CONSTRAINT `fk_carryover_project_receivable` FOREIGN KEY (`receivable_id`) REFERENCES `db_finance_receivable` (`receivable_id`),
  CONSTRAINT `fk_carryover_project_result` FOREIGN KEY (`project_id`) REFERENCES `db_project` (`project_id`),
  CONSTRAINT `fk_carryover_project_store` FOREIGN KEY (`store_id`) REFERENCES `db_tenant_store` (`store_id`),
  CONSTRAINT `fk_carryover_project_team` FOREIGN KEY (`team_id`) REFERENCES `db_tenant_team` (`team_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='单项目业务承接';
