  KEY `FK2vl1ivc7jxookw52inm71hrqc` (`property_id`),
  KEY `FKsr0fxm8orm2c3r10pncu8xpqt` (`store_id`),
  KEY `FK38vs6e6vnc6sa1uj80d6edkhp` (`generation_id`),
