INSERT INTO `db_tenant_plan` VALUES (1790208367859757558,'体验版','free-quote',20260924,20260924080607,24,8,6,9,7,80607,3,2026,0,'1 家门店、2 个席位，全功能能力',_binary '','基础客户与报价能力;适合个人工作室首次上线;无需支付年费',2,1,'Crm,Design,Quote,Project,Supply,Finance,Analytics,Ai,Api','免费报价版',_binary '\0',0,0,0,_binary '\0','低门槛启用装企数字化',20260924,20260924080607,24,8,6,9,7,80607,3,2026),(1790208367900511984,'单店首选','annual-basic',20260924,20260924080607,24,8,6,9,7,80607,3,2026,365,'单店起步，全功能经营，限制为 1 家门店和 5 个席位',_binary '','注册赠送 14 天免费试用;客户到签约经营闭环;设计、报价、项目管理;5 个员工席位',5,1,'Crm,Design,Quote,Project,Supply,Finance,Analytics,Ai,Api','基础版年费',_binary '\0',598000,598000,10,_binary '\0','单店经营全流程，一次开通全年可用',20260924,20260924080607,24,8,6,9,7,80607,3,2026),(1790208367910210092,'最受欢迎','annual-pro',20260924,20260924080607,24,8,6,9,7,80607,3,2026,365,'成长型多店装企，包含完整经营、财务和供应链闭环',_binary '','3 家门店、15 个席位;供应链与财务结算;经营分析看板;适合成长型多店装企',15,3,'Crm,Design,Quote,Project,Supply,Finance,Analytics,Ai,Api','专业版年费',_binary '\0',1198000,1198000,20,_binary '','从增长到盈利，一套系统管全店',20260924,20260924080607,24,8,6,9,7,80607,3,2026),(1790208367919622684,'连锁进阶','annual-flagship',20260924,20260924080607,24,8,6,9,7,80607,3,2026,365,'连锁和多品牌装企，包含多门店、开放接口、实施陪跑和高级经营能力',_binary '','不限门店、30 个席位;AI 与开放接口;全模块经营体系;专属上线实施支持',30,9999,'Crm,Design,Quote,Project,Supply,Finance,Analytics,Ai,Api','旗舰版年费',_binary '\0',2180000,2180000,30,_binary '\0','连锁扩张与品牌管控的完整底座',20260924,20260924080607,24,8,6,9,7,80607,3,2026);
